'use strict';

// MODULES //

var tape = require( 'tape' );
var Float64Array = require( '@stdlib/array/float64' );
var discreteUniform = require( '@stdlib/random/array/discrete-uniform' );
var isAlmostEqual = require( '@stdlib/assert/is-almost-equal-float64array' );
var dlarf1f = require( '@stdlib/lapack/base/dlarf1f' ).ndarray;
var min = require( '@stdlib/math/base/special/min' );
var dgelqf = require( './../lib/dgelqf.js' );


// VARIABLES //

var opts = {
	'dtype': 'float64'
};


// FIXTURES //

var UNBLOCKED = require( './fixtures/unblocked.json' );
var BLOCKED = require( './fixtures/blocked.json' );


// FUNCTIONS //

/**
* Verifies that the orthogonal matrix Q satisfies Q^T * Q = I by checking that a random vector x is recovered after applying Q then Q^T.
*
* @private
* @param {Float64Array} A - matrix after `dgelqf` (contains R and Householder vectors)
* @param {Float64Array} TAU - scalar factors of the elementary reflectors
* @param {NonNegativeInteger} M - number of rows in A
* @param {NonNegativeInteger} N - number of columns in A
* @param {NonNegativeInteger} LDA - leading dimension of A
* @param {NonNegativeInteger} maxULP - maximum allowed ULP difference
* @returns {boolean} true if the round-trip recovers x within maxULP ULPs
*/
function verifyQOrthogonal( A, TAU, M, N, LDA, maxULP ) { // eslint-disable-line stdlib/vars-order
	var work = new Float64Array( M );
	var x = discreteUniform( M, 100.0, 200.0, opts );
	var xOrig = new Float64Array( x );
	var y = new Float64Array( x );
	var K = min( M, N );
	var i;

	// y = Q * x
	for ( i = 0; i < K; i++ ) {
		if ( TAU[ i ] !== 0.0 ) {
			dlarf1f( 'left', N - i, 1, A, LDA, i + ( i * LDA ), TAU[ i ], y, 1, N, i, work, 1, 0 );
		}
	}

	// y = Q^T * (Q * x) = x
	for ( i = K - 1; i >= 0; i-- ) {
		if ( TAU[ i ] !== 0.0 ) {
			dlarf1f( 'left', N - i, 1, A, LDA, i + ( i * LDA ), TAU[ i ], y, 1, N, i, work, 1, 0 );
		}
	}

	return isAlmostEqual( y, xOrig, maxULP );
}


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof dgelqf, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function has an arity of 8', function test( t ) {
	t.strictEqual( dgelqf.length, 8, 'returns expected value' );
	t.end();
});

tape( 'the function throws an error if provided a first argument which is not a valid order', function test( t ) {
	var values;
	var WORK;
	var TAU;
	var A;
	var i;

	A = new Float64Array( [ 1, 5, 9, 2, 6, 10, 3, 7, 11, 4, 8, 12 ] );
	TAU = new Float64Array( 3 );
	WORK = new Float64Array( 4 );

	values = [
		'foo',
		'bar',
		'beep',
		'boop',
		-5,
		NaN,
		true,
		false,
		null,
		void 0,
		[],
		{},
		function noop() {}
	];

	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[ i ] ), TypeError, 'throws an error when provided ' + values[ i ] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			dgelqf( value, 3, 4, A, 3, TAU, WORK, 4 );
		};
	}
});

