tape( 'the function quick returns when `LWORK` is equal to -1', function test( t ) {
	var expectedWORK;
	var expectedTAU;
	var expectedA;
	var info;
	var data;
	var WORK;
	var TAU;
	var A;

	data = UNBLOCKED;

	A = new Float64Array( data.A );
	TAU = new Float64Array( data.TAU );
	WORK = new Float64Array( data.WORK );

	expectedA = new Float64Array( data.A );
	expectedTAU = new Float64Array( data.TAU );
	expectedWORK = new Float64Array( data.WORK );
	expectedWORK[ 0 ] = 96;

	info = dgelqf( data.order, data.M, data.N, A, data.LDA, TAU, WORK, -1 );
	t.strictEqual( info, 0, 'returns expected value' );
	t.strictEqual( isAlmostEqual( A, expectedA, 1 ), true, 'returns expected value' );
	t.strictEqual( isAlmostEqual( TAU, expectedTAU, 1 ), true, 'returns expected value' );
	t.strictEqual( isAlmostEqual( WORK, expectedWORK, 1 ), true, 'returns expected value' );

	expectedWORK[ 0 ] = 1;

	info = dgelqf( data.order, data.M, 0, A, data.LDA, TAU, WORK, -1 );
	t.strictEqual( info, 0, 'returns expected value' );
	t.strictEqual( isAlmostEqual( A, expectedA, 1 ), true, 'returns expected value' );
	t.strictEqual( isAlmostEqual( TAU, expectedTAU, 1 ), true, 'returns expected value' );
	t.strictEqual( isAlmostEqual( WORK, expectedWORK, 1 ), true, 'returns expected value' );
	t.end();
});

