tape( 'the function computes a LQ factorization (unblocked, column-major)', function test( t ) {
	var expectedWORK;
	var expectedTAU;
	var expectedA;
	var info;
	var data;
	var WORK;
	var TAU;
	var A;

	data = UNBLOCKED;

	A = new Float64Array( data.A );
	TAU = new Float64Array( data.TAU );
	WORK = new Float64Array( data.WORK );

	expectedA = new Float64Array( data.A_out );
	expectedTAU = new Float64Array( data.TAU_out );
	expectedWORK = new Float64Array( data.WORK_out );

	info = dgelqf( data.order, data.M, data.N, A, data.LDA, TAU, WORK, data.LWORK ); // eslint-disable-line max-len
	t.strictEqual( info, 0, 'returns expected value' );
	t.strictEqual( isAlmostEqual( A, expectedA, 1 ), true, 'returns expected value' );
	t.strictEqual( isAlmostEqual( TAU, expectedTAU, 1 ), true, 'returns expected value' );
	t.strictEqual( isAlmostEqual( WORK, expectedWORK, 1 ), true, 'returns expected value' );
	t.end();
});

tape( 'the function computes a LQ factorization (blocked, column-major)', function test( t ) {
	var info;
	var data;
	var WORK;
	var TAU;
	var A;

	data = BLOCKED;

	A = new Float64Array( data.A );
	TAU = new Float64Array( data.TAU );
	WORK = new Float64Array( data.WORK );

	info = dgelqf( data.order, data.M, data.N, A, data.LDA, TAU, WORK, data.LWORK ); // eslint-disable-line max-len
	t.strictEqual( info, 0, 'returns expected value' );
	t.strictEqual( WORK[ 0 ], 4128, 'first element of WORK is iws' );
	t.ok( verifyQOrthogonal( A, TAU, data.M, data.N, data.LDA, 100 ), 'round-trip Q^T * (Q * x) recovers x' );
	t.end();
});

tape( 'the function computes a LQ factorization (reduced blocksize)', function test( t ) {
	var LWORK;
	var info;
	var WORK;
	var LDA;
	var TAU;
	var A;
	var i;
	var M;
	var N;

	M = 129;
	N = 129;
	LDA = 129;
	LWORK = 516;

	A = new Float64Array( M * N );
	for ( i = 0; i < M * N; i++ ) {
		A[ i ] = i + 1;
	}
	TAU = new Float64Array( min( M, N ) );
	WORK = new Float64Array( LWORK );

	info = dgelqf( 'column-major', M, N, A, LDA, TAU, WORK, LWORK );
	t.strictEqual( info, 0, 'returns expected value' );
	t.strictEqual( WORK[ 0 ], 4128, 'first element of WORK is iws' );
	t.ok( verifyQOrthogonal( A, TAU, M, N, LDA, 100 ), 'round-trip Q^T * (Q * x) recovers x' );
	t.end();
});
